 private void showMethod(boolean qr){qrMode=qr;linkPanel.setVisibility(qr?View.GONE:View.VISIBLE);qrPanel.setVisibility(qr?View.VISIBLE:View.GONE);Button[] tabs={linkTab,qrTab};int[] icons={R.drawable.ui_external,R.drawable.ui_import};for(int i=0;i<2;i++){boolean active=(i==1)==qr;AppIcons.ripple(tabs[i],round(active?SOFT:Color.TRANSPARENT));tabs[i].setTextColor(active?RED:MUTED);tabs[i].setSelected(active);AppIcons.apply(tabs[i],icons[i],active?RED:MUTED,18);}if(send!=null){send.setVisibility(qr?View.GONE:View.VISIBLE);}if(qr){link.clearFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(link.getWindowToken(),0);}}
 private void pickQr(){if(reading||manager==null||manager.busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(i,23);}catch(ActivityNotFoundException e){showError("ไม่พบแอปสำหรับเลือกรูป กรุณาวางลิงก์ซองแทน");}}
 private void confirm(){if(manager==null||manager.busy||reading)return;if(qrMode){pickQr();return;}final String canonical;try{canonical="https://gift.truemoney.com/campaign/?v="+DonationClient.code(link.getText().toString());}catch(IllegalArgumentException e){showError(e.getMessage());return;}
  new AlertDialog.Builder(this).setTitle("ยืนยันบริจาคให้ Rin23?").setMessage("ผู้รับบริจาค: Rin23\n\nเมื่อกดยืนยัน แอปจะส่งคำขอรับเงินจากซองนี้ทันที จำนวนเงินเป็นไปตามสิทธิ์ที่ได้รับในซอง\n\nการบริจาคเป็นความสมัครใจ แอปใช้ฟรีเหมือนเดิม").setNegativeButton("ยกเลิก",null).setPositiveButton("ยืนยันบริจาค",(dialog,which)->{link.setText("");manager.donate(canonical);}).show();
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=23||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(!"content".equals(uri.getScheme())){showError("ไม่สามารถอ่านรูปนี้ได้");return;}reading=true;changed();statusBox.setVisibility(View.VISIBLE);message.setText("กำลังอ่าน QR ในเครื่อง…");
  imageWorker.execute(()->{Bitmap bitmap=null;String found=null,error=null;try{
   bitmap=ImageDecoder.decodeBitmap(ImageDecoder.createSource(getContentResolver(),uri),(decoder,info,src)->{int w=info.getSize().getWidth(),h=info.getSize().getHeight();double scale=Math.max(1.0,Math.max(w,h)/2048.0);decoder.setTargetSize(Math.max(1,(int)(w/scale)),Math.max(1,(int)(h/scale)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});
   int w=bitmap.getWidth(),h=bitmap.getHeight();int[] pixels=new int[w*h];bitmap.getPixels(pixels,0,w,0,0,w,h);found=VoucherQrReader.decode(pixels,w,h);
  }catch(Exception|OutOfMemoryError e){error=e instanceof IllegalArgumentException?e.getMessage():"อ่านรูปไม่ได้ กรุณาเลือกรูป QR ที่ชัด หรือวางลิงก์ซองแทน";}finally{if(bitmap!=null)bitmap.recycle();}
  final String value=found,err=error;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;reading=false;changed();if(value!=null){link.setText(value);showMethod(false);statusBox.setVisibility(View.VISIBLE);message.setText("อ่านลิงก์ซองได้แล้ว ตรวจสอบแล้วกดปุ่มยืนยันบริจาค • ยังไม่ได้ส่งซอง");message.setTextColor(TEXT);}else showError(err);});});
 }
 public void changed(){if(manager==null)return;boolean busy=manager.busy||reading;send.setEnabled(!busy);send.setAlpha(busy?0.6f:1f);send.setText(busy?(reading?"กำลังอ่าน QR…":"กำลังดำเนินการ…"):"ตรวจสอบและยืนยันบริจาค");pick.setEnabled(!busy);linkTab.setEnabled(!busy);qrTab.setEnabled(!busy);link.setEnabled(!busy);spinner.setVisibility(busy?View.VISIBLE:View.GONE);statusBox.setVisibility(busy||!manager.message.equals("บริจาคโดยสมัครใจ แอปใช้ฟรีเหมือนเดิม")?View.VISIBLE:View.GONE);message.setText(reading?"กำลังอ่าน QR ในเครื่อง…":manager.message);message.setTextColor(manager.succeeded?palette.success:MUTED);
  String signature=manager.message+manager.busy;if(!signature.equals(historySignature)){historySignature=signature;history.removeAllViews();try{List<DonationStore.Entry> entries=manager.history();if(entries.isEmpty()){LinearLayout empty=card();LinearLayout line=row();line.addView(AppIcons.view(this,R.drawable.ui_heart,MUTED,26),new LinearLayout.LayoutParams(dp(40),dp(40)));LinearLayout copy=column();copy.setPadding(dp(10),0,0,0);copy.addView(text("ยังไม่มีรายการสนับสนุน",14,TEXT));TextView caption=text("เมื่อส่งซองแล้ว ประวัติจะแสดงที่นี่",11,MUTED);caption.setPadding(0,dp(4),0,0);copy.addView(caption);line.addView(copy,new LinearLayout.LayoutParams(0,-2,1));empty.addView(line);history.addView(empty);}for(DonationStore.Entry e:entries){LinearLayout c=card();String status=e.state.equals("succeeded")?"สำเร็จ • "+DonationClient.baht(e.amount)+" บาท":e.state.equals("unknown")||e.state.equals("submitted")?"ยังยืนยันผลไม่ได้":e.state.equals("checking")?"กำลังตรวจสอบ":e.state.equals("not_sent")?"ยังไม่ได้ส่งคำขอ":"รับซองไม่สำเร็จ";TextView statusTitle=text(status,14,e.state.equals("succeeded")?palette.success:TEXT);statusTitle.setTypeface(Typeface.DEFAULT,Typeface.BOLD);AppIcons.apply(statusTitle,e.state.equals("succeeded")?R.drawable.ui_heart:R.drawable.ui_info,e.state.equals("succeeded")?palette.success:MUTED,18);statusTitle.setPadding(0,0,0,dp(8));c.addView(statusTitle);c.addView(text(new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("th","TH")).format(new Date(e.time)),11,MUTED));TextView detail=text(e.message,11,MUTED);detail.setPadding(0,dp(8),0,0);c.addView(detail);TextView ref=text("เลขรายการในเครื่อง: "+e.receipt,10,MUTED);ref.setTextIsSelectable(true);ref.setPadding(0,dp(6),0,0);c.addView(ref);history.addView(c);}}catch(Exception e){history.addView(text("อ่านประวัติไม่ได้ กรุณาอย่าส่งซ้ำจนตรวจสอบผลแล้ว",12,MUTED));}}
 }
 private void showError(String s){statusBox.setVisibility(View.VISIBLE);message.setText(s);message.setTextColor(RED);}
 private LinearLayout row(){LinearLayout l=column();l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 private LinearLayout card(){LinearLayout l=column();l.setPadding(dp(16),dp(16),dp(16),dp(16));l.setBackground(round(PANEL));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);p.bottomMargin=dp(14);l.setLayoutParams(p);return l;}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 private Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(primary?ON_ACCENT:TEXT);b.setBackground(round(primary?RED:PANEL));b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(18),0,dp(18),0);b.setStateListAnimator(null);AppIcons.ripple(b,round(primary?RED:PANEL));return b;}
 private GradientDrawable round(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(20));if(color==PANEL)d.setStroke(dp(1),BORDER);return d;}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putBoolean("qrMode",qrMode);}
 @Override protected void onStart(){super.onStart();if(manager!=null)manager.observe(this);}
 @Override protected void onStop(){if(manager!=null)manager.unobserve(this);super.onStop();}
 @Override protected void onDestroy(){imageWorker.shutdownNow();super.onDestroy();}
